import pytest


class BadInput(Exception):
    def __init__(self, text: str) -> None:
        self.text = text


def sum_parsed(xs: list[str]) -> int:
    """Parse every string in xs as an integer and return their sum.

    Raises BadInput carrying the first string that is not an integer.
    An empty list sums to 0.
    """
    total = 0
    for s in xs:
        try:
            total += int(s)
        except ValueError:
            raise BadInput(s) from None
    return total


def test_sum_basic() -> None:
    assert sum_parsed(["1", "2", "3"]) == 6


def test_sum_empty() -> None:
    assert sum_parsed([]) == 0


def test_sum_negative_and_signed() -> None:
    assert sum_parsed(["-5", "+3", "10"]) == 8


def test_sum_whitespace_tolerated() -> None:
    assert sum_parsed([" 4 ", "6"]) == 10


def test_bad_input_raises() -> None:
    with pytest.raises(BadInput) as exc:
        sum_parsed(["1", "x", "3"])
    assert exc.value.text == "x"


def test_first_bad_reported() -> None:
    with pytest.raises(BadInput) as exc:
        sum_parsed(["1", "2.5", "abc"])
    assert exc.value.text == "2.5"


def test_empty_string_is_bad() -> None:
    with pytest.raises(BadInput) as exc:
        sum_parsed(["1", ""])
    assert exc.value.text == ""


def test_bad_text_preserved_exactly() -> None:
    with pytest.raises(BadInput) as exc:
        sum_parsed(["7", " x "])
    assert exc.value.text == " x "


def test_large_values() -> None:
    big = 10**30
    assert sum_parsed([str(big), "1"]) == big + 1

